const sourcesResult = $json;
const sourceItems = sourcesResult.sources || [];
const topic = sourcesResult.topic;
const topicArchive = ($('Fetch Recent Topics').item.json.recent || []).map((t) => `${t.tool_name}: ${t.topic} (${t.category})`);
if (sourceItems.length < 1) throw new Error('RESEARCH_INSUFFICIENT_TOOL_SIGNALS');
const topicShape = {topic:'',tool_name:'',category:'',one_line_value:'',developer_workflow:'',who_it_helps:'',why_now:'',hook:'',why_it_matters:'',visual_angle:'',trend_score:0,claims:[{claim_id:'c1',statement:'',source_url:'',publisher:'',published_at:'',retrieved_at:new Date().toISOString(),confidence:0,verification_notes:''}],seo_brief:{primary_keyword:'',related_keywords:[''],search_intent:'informational|commercial|tutorial',title_options:['','',''],description:'',hashtags:['']}};
const schema = {recommended_topic:topicShape,candidates:[topicShape],research_policy:{requires_human_review:true,content_disclosure:'AI-assisted research and narration; edited visuals.'}};
const excludeList = (topic.excludeTerms || []).join(', ');
const prompt = `You are an evidence-first researcher and SEO strategist for ${topic.displayName}, a short video show aimed at software developers. Analyze only the QUALIFIED SOURCE MATERIAL below, which has already been filtered for topic relevance. Never invent product capabilities, adoption numbers, pricing, release dates, or market claims.

This show covers ONLY ${topic.scope} Reject every candidate outside that scope, even a strong one${excludeList ? ` -- explicitly excluded: ${excludeList}` : ''} -- a sibling show already covers other developer topics, and diluting this pool is exactly the mistake this show exists to avoid. If fewer than 5 source items are genuinely in scope, return fewer candidates rather than stretching the definition. Explain the concrete developer workflow improved.

Prefer recent releases, authoritative sources, independent corroboration, specific capabilities, and clear search intent. Reject generic AI news, consumer-only apps, vague thought leadership, fabricated claims, speculation, and tools without a concrete developer use case.

For the hook field: write it as a genuine tension a developer would want resolved, not a headline summary. Use one of: a contrarian claim ("X breaks the rule everyone follows about Y"), a mistake warning ("most developers get Z wrong"), a numbered promise ("N things changed"), or a concrete before/after gap. Sharpen the framing, never the facts -- the hook must still be fully supported by the claims.

${topicArchive.length ? `PERMANENT EXCLUSION ARCHIVE -- videos already rendered or rejected: ${topicArchive.join('; ')}. Never choose any archived tool or substantially equivalent topic, even if it has a new release or slightly different name.` : ''}

Choose exactly 5 distinct candidates from different categories when the evidence allows, ranked best-first. recommended_topic must equal candidates[0]. Every candidate must include the full evidence and SEO fields shown in the schema, including at least one exact source-backed claim, so any unused candidate can safely replace the first choice. Use two independent sources per candidate when available. Every factual claim must cite an exact source_url from the material.

Create an SEO brief around natural developer search language. Titles should promise a concrete, specific benefit -- prefer a number, a contrast, or a named limitation over generic phrasing like "X: what it does", so the title creates a real curiosity gap while staying literally true to the evidence. Limit hashtags to 5-8.

Return ONLY valid JSON matching this schema:
${JSON.stringify(schema)}

QUALIFIED SOURCE MATERIAL:
${JSON.stringify(sourceItems)}`;
return [{json:{prompt, source_count: sourceItems.length, sources: sourceItems, topic, scoring_version:'topic-research-v1'}}];

const originalPrompt = $items('Build Research Prompt')[0]?.json?.prompt ?? '';
const statusCode = Number($json.statusCode ?? 200);
const body = $json.body ?? $json;
const text = Array.isArray(body?.content) ? body.content.filter((block) => block?.type === 'text' && typeof block.text === 'string').map((block) => block.text).join('\n').trim() : '';
const errorType = String(body?.error?.type ?? body?.type ?? '').trim();
if (statusCode >= 200 && statusCode < 300 && text) {
  return [{ json: { use_qwen_fallback: false, response: text, research_provider: 'anthropic', research_model: body?.model ?? 'claude', prompt: originalPrompt } }];
}
const fallbackReason = statusCode < 200 || statusCode >= 300 ? `${statusCode}_${errorType || 'http_error'}` : 'empty_response';
return [{ json: { use_qwen_fallback: true, prompt: originalPrompt, research_provider: 'qwen-fallback', fallback_reason: fallbackReason } }];

const payload = $json;
let raw = '';
if (typeof payload === 'string') raw = payload;
else if (typeof payload.body === 'string') raw = payload.body;
else if (typeof payload.data === 'string') raw = payload.data;
else if (typeof payload.response === 'string') raw = payload.response;
else raw = JSON.stringify(payload);
if (!raw) throw new Error('RESEARCH_EMPTY_RESPONSE');
let generated = raw;
try { generated = JSON.parse(raw).response ?? raw; } catch {
  const lines = raw.split(/\r?\n/).filter(Boolean);
  const chunks = [];
  let isNdjson = lines.length > 1;
  for (const line of lines) {
    try { chunks.push(JSON.parse(line)); } catch { isNdjson = false; break; }
  }
  if (isNdjson && chunks.every((chunk) => typeof chunk.response === 'string')) generated = chunks.map((chunk) => chunk.response).join('');
}
const fenced = generated.match(/```(?:json)?\s*([\s\S]*?)```/i);
const candidate = String(fenced?.[1] ?? generated).trim();
let research;
const end = candidate.lastIndexOf('}');
for (const start of [0, ...[...candidate.matchAll(/\{/g)].map((match) => match.index)]) {
  if (end < start) continue;
  try {
    const parsed = JSON.parse(candidate.slice(start, end + 1));
    const genuinelyEmpty = parsed?.recommended_topic === null && Array.isArray(parsed?.candidates) && parsed.candidates.length === 0;
    if (parsed?.recommended_topic?.claims?.length || genuinelyEmpty) { research = parsed; break; }
  } catch {}
}
if (!research) return [{ json: { parse_failed: true, parse_failure_reason: 'no valid JSON object with recommended_topic.claims found' } }];
const provider = payload.research_provider ?? 'qwen-fallback';
const model = payload.research_model ?? 'tushin-agent:latest';
return [{ json: { research, researched_at: new Date().toISOString(), research_provider: provider, model, requires_human_review: true } }];

const statusCode = Number($json.statusCode ?? 200);
const body = $json.body ?? $json;
if (statusCode === 400 || statusCode >= 500) throw new Error(`RESEARCH_VALIDATE_INFRA_ERROR:${statusCode}:${JSON.stringify(body).slice(0, 300)}`);
return [{json: body}];

const original = $('Build Research Prompt').item.json;
const validation = $json;
const reasons = validation.parse_failed ? 'Your previous response could not be parsed as valid JSON matching the required schema.' : (Array.isArray(validation.reasons) ? validation.reasons.join('; ') : (validation.failureCode ?? 'validation failed'));
const prompt = `${original.prompt}\n\nYOUR PREVIOUS SUBMISSION WAS REJECTED for the following reason(s): ${reasons}. Fix these specific problems in your new answer -- stay strictly within the same topic scope and evidence set, and cite only source_url values that appear in the QUALIFIED SOURCE MATERIAL above.`;
return [{json: {prompt, source_count: original.source_count, sources: original.sources, topic: original.topic, scoring_version: original.scoring_version, retry: true}}];

