const research = $json.research;
const recommended = research?.recommended_topic;
if (!recommended) throw new Error('JUDGEMENT_QUEUE_MISSING_RECOMMENDED_TOPIC');
const sameCandidate = (a, b) => String(a?.tool_name ?? '').trim() === String(b?.tool_name ?? '').trim()
  && String(a?.topic ?? '').trim() === String(b?.topic ?? '').trim();
const rest = (Array.isArray(research.candidates) ? research.candidates : []).filter((candidate) => !sameCandidate(candidate, recommended));
const queue = [recommended, ...rest];
return [{json: {...$json, research, judgement_queue: queue, judgement_index: 0}}];

const queue = Array.isArray($json.judgement_queue) ? $json.judgement_queue : [];
const index = Number($json.judgement_index ?? 0);
const candidate = queue[index];
if (!candidate) throw new Error(`JUDGEMENT_QUEUE_EMPTY:${index}_OF_${queue.length}`);
const topic = $('Fetch Topic-Specific Research Sources').item.json.topic;
const excludeList = (topic.excludeTerms || []).join(', ');
const schema = {worth_it: true, topic_match: true, confidence: 0.0, reason: '', failure_mode: 'not_actually_new|generic_ai_news|insufficient_evidence|no_developer_workflow|off_topic|null'};
const prompt = `You are the pre-production judge for a short trend video series about ${topic.displayName}. This show covers ONLY ${topic.scope}${excludeList ? ` Explicitly excluded: ${excludeList}.` : ''}

Your job has two parts. FIRST, confirm the idea below genuinely belongs to that scope -- set topic_match to false and worth_it to false and failure_mode to "off_topic" if it does not, regardless of how newsworthy it otherwise is. SECOND, only if it is in scope: decide whether this is a genuine, well-evidenced developer-relevant trend right now, not generic AI news, not speculation, and not something every developer already knows about.

Reject the candidate (worth_it: false) if it is generic AI news with no concrete developer workflow impact (failure_mode: generic_ai_news), if the evidence is too thin or unclear to support the claim (failure_mode: insufficient_evidence), if it lacks a concrete developer workflow this changes (failure_mode: no_developer_workflow), or if it is not actually new or noteworthy right now (failure_mode: not_actually_new).

IDEA UNDER REVIEW:
${JSON.stringify({tool_name: candidate.tool_name, topic: candidate.topic, category: candidate.category, hook: candidate.hook, developer_workflow: candidate.developer_workflow, why_now: candidate.why_now, who_it_helps: candidate.who_it_helps})}

Return ONLY valid JSON matching this schema:
${JSON.stringify(schema)}`;
return [{json: {...$json, candidate, prompt}}];

const state = $('Build Judgement Prompt').item.json;
const statusCode = Number($json.statusCode ?? 200);
const body = $json.body ?? $json;
const text = Array.isArray(body?.content) ? body.content.filter((block) => block?.type === 'text' && typeof block.text === 'string').map((block) => block.text).join('\n').trim() : '';
const errorType = String(body?.error?.type ?? body?.type ?? '').trim();
if (statusCode >= 200 && statusCode < 300 && text) {
  return [{json: {use_qwen_fallback: false, response: text, judge_provider: 'anthropic', research: state.research, judgement_queue: state.judgement_queue, judgement_index: state.judgement_index, candidate: state.candidate}}];
}
const fallbackReason = statusCode < 200 || statusCode >= 300 ? `${statusCode}_${errorType || 'http_error'}` : 'empty_response';
return [{json: {use_qwen_fallback: true, prompt: state.prompt, judge_provider: 'qwen-fallback', fallback_reason: fallbackReason, research: state.research, judgement_queue: state.judgement_queue, judgement_index: state.judgement_index, candidate: state.candidate}}];

const state = $('Route Claude Judgement Result').item.json;
const payload = $json;
let raw = '';
if (typeof payload.response === 'string') raw = payload.response;
else if (typeof payload === 'string') raw = payload;
else if (typeof payload.data === 'string') raw = payload.data;
else if (typeof payload.body === 'string') raw = payload.body;
else raw = JSON.stringify(payload);
let generated = raw;
try { generated = JSON.parse(raw).response ?? raw; } catch {
  const lines = raw.split(/\r?\n/).filter(Boolean);
  const chunks = [];
  let isNdjson = lines.length > 1;
  for (const line of lines) {
    try { chunks.push(JSON.parse(line)); } catch { isNdjson = false; break; }
  }
  if (isNdjson && chunks.every((chunk) => typeof chunk.response === 'string')) generated = chunks.map((chunk) => chunk.response).join('');
}
const fenced = String(generated ?? '').match(/```(?:json)?\s*([\s\S]*?)```/i);
const candidateText = String(fenced?.[1] ?? generated ?? '').trim();
let verdict = null;
const end = candidateText.lastIndexOf('}');
for (const start of [0, ...[...candidateText.matchAll(/\{/g)].map((match) => match.index)]) {
  if (end < start) continue;
  try {
    const parsed = JSON.parse(candidateText.slice(start, end + 1));
    if (typeof parsed.worth_it === 'boolean') { verdict = parsed; break; }
  } catch {}
}
const worthIt = verdict ? Boolean(verdict.worth_it) : false;
const topicMatch = verdict ? Boolean(verdict.topic_match) : false;
const reason = verdict ? String(verdict.reason ?? '') : 'JUDGEMENT_PARSE_FAILED';
const failureMode = verdict ? (verdict.failure_mode ?? null) : 'judgement_unparseable';
const research = state.research;
const candidate = state.candidate;
const updatedResearch = {...research, recommended_topic: candidate};
return [{json: {worth_it: worthIt, topic_match: topicMatch, reason, failure_mode: failureMode, research: updatedResearch, candidate, judgement_queue: state.judgement_queue, judgement_index: state.judgement_index}}];

const state = $('Normalize Judgement Verdict').item.json;
const queue = Array.isArray(state.judgement_queue) ? state.judgement_queue : [];
const nextIndex = Number(state.judgement_index ?? 0) + 1;
return [{json: {judgement_queue: queue, judgement_index: nextIndex, has_more_candidates: nextIndex < queue.length, research: state.research}}];

const research = $json.research;
const topic = research?.recommended_topic;
if (!topic) throw new Error('SEO_MISSING_RECOMMENDED_TOPIC');
const incoming = topic.seo_brief ?? {};
const toolName = String(topic.tool_name ?? topic.topic ?? 'AI developer tool').trim();
const primaryKeyword = String(incoming.primary_keyword ?? `${toolName} for developers`).trim();
const relatedKeywords = [...new Set((Array.isArray(incoming.related_keywords) ? incoming.related_keywords : []).map((value) => String(value).trim()).filter(Boolean))].slice(0, 8);
const titleOptions = [...new Set((Array.isArray(incoming.title_options) ? incoming.title_options : []).map((value) => String(value).trim()).filter(Boolean))].slice(0, 5);
if (!titleOptions.length) titleOptions.push(`${toolName}: the developer workflow it improves`);
const hashtags = [...new Set((Array.isArray(incoming.hashtags) ? incoming.hashtags : []).map((value) => `#${String(value).replace(/^#/, '').replace(/[^A-Za-z0-9_]/g, '')}`).filter((value) => value.length > 1))].slice(0, 8);
for (const fallback of ['#AITools', '#DeveloperTools', '#Coding']) { if (hashtags.length >= 5) break; if (!hashtags.includes(fallback)) hashtags.push(fallback); }
const seoBrief = { primary_keyword: primaryKeyword, related_keywords: relatedKeywords, search_intent: incoming.search_intent ?? 'informational', title_options: titleOptions, description: String(incoming.description ?? topic.one_line_value ?? topic.why_it_matters ?? '').trim(), hashtags };
research.recommended_topic.seo_brief = seoBrief;
return [{ json: { ...$json, research, seo_brief: seoBrief } }];

const research = $items('Finalize SEO Brief')[0]?.json?.research;
if (!research?.recommended_topic) throw new Error('SCRIPT_MISSING_RESEARCH');
const topic = research.recommended_topic;
const prompt = `Write a clean, evidence-based dialogue for a 30–60 second vertical video about the recommended AI developer tool below. Return exactly six short alternating turns, beginning with Peter.

Dialogue structure -- this is an ARGUMENT, not a briefing. Peter and Stewie hold opposing positions on the tool and push back on each other's specific words; neither one just explains something to a passive listener.
1. Peter opens with the hook: the single boldest, most surprising claim about the tool, stated in one short sentence of 18 words or fewer -- a stance, not a description. This line is the only thing standing between the viewer and a scroll past, so it must land in the first 5-10 seconds and cannot be buried behind a wind-up, a greeting, or context-setting.
2. Stewie directly disagrees, naming a real limitation, cost, or reason to doubt the claim.
3. Peter defends the claim with one concrete, evidence-backed detail that answers Stewie's specific objection.
4. Stewie escalates with a sharper counter-argument or a harder edge case -- not a generic "how is it useful" question.
5. Peter counters again with a second specific, evidence-backed point that directly rebuts turn 4.
6. Stewie delivers a genuine verdict: concede the point while landing a final jab, or hold the disagreement -- never a neat, tidy agreement. The tension should feel unresolved enough that the viewer picks a side.

Focus on one primary tool and one coherent use case. Do not combine unrelated products, models, or claims in the same dialogue. Every turn must be one sentence: complete, conversational, and written with simple grammar and a clear subject. Turn 0's 18-word hook limit is a hard requirement, not a suggestion -- before returning, count its words and shorten it if it runs long, since a slow opening line is a failed video even if every other turn is perfect. Keep the dialogue natural and conversational with no filler or padding. Peter is plain-spoken, confident, and mildly funny; Stewie is precise, skeptical, and cutting. They are arguing with each other, not narrating to the camera. Keep every line clean, natural, and easy to say aloud. Name the tool early, use the primary SEO keyword naturally at most once, and never include stage directions, headings, URLs, profanity, keyword stuffing, sentence fragments, or unsupported hype. Use only facts from the research package.

After writing the dialogue, plan 8–12 distinct visual cues. Every one of the six turns (turn_index 0 through 5) MUST appear in the visuals array at least once — this is a hard requirement, not a suggestion. Before returning, re-read your own six turns and check that turn_index 0, 1, 2, 3, 4, and 5 each appear at least once in visuals; if any turn is missing, add a cue for it before adding a second cue to a denser turn. A turn with zero cues fails the whole video, so never skip one because it feels abstract — find the most literal, concrete thing that turn's line could point to (a specific UI element, a specific number, a reaction shot) rather than leaving it uncovered. Each cue must name an exact phrase spoken in its zero-based turn_index, a focused image-search query, kind logo or screenshot, a visual_purpose of identity, interface, mechanism, outcome, evidence, reaction, or context, and a source_url to the exact product, documentation, repository, or evidence page. Prefer official UI screenshots, GitHub README diagrams, code, terminal output, benchmarks, and readable product imagery. Stock images are allowed only for reaction or context and must never serve as evidence for a named product. Never request generic approval/review imagery, generic article headers, government documents, unrelated products, or repeated variants of the same artwork. Claude Vision will reject irrelevant candidates and the run will fail unless eight distinct images survive, so choose visually provable beats and precise queries.

Return ONLY JSON: {"title":"","focus":"","turns":[{"speaker":"peter","text":""},{"speaker":"stewie","text":""},{"speaker":"peter","text":""},{"speaker":"stewie","text":""},{"speaker":"peter","text":""},{"speaker":"stewie","text":""}],"visuals":[{"turn_index":0,"phrase":"exact spoken phrase","query":"tool name screenshot","kind":"screenshot","visual_purpose":"interface","source_url":"https://official-source-page"}]}
RECOMMENDED RESEARCH:
${JSON.stringify(topic)}`;
return [{ json: { prompt, research, seo_brief: $items('Finalize SEO Brief')[0]?.json?.seo_brief } }];

const promptItem = $items('Build Peter and Stewie Dialogue Prompt')[0]?.json ?? {};
const statusCode = Number($json.statusCode ?? 200);
const body = $json.body ?? $json;
const text = Array.isArray(body?.content) ? body.content.filter((block) => block?.type === 'text' && typeof block.text === 'string').map((block) => block.text).join('\n').trim() : '';
const errorType = String(body?.error?.type ?? body?.type ?? '').trim();
let dialogueValid = false;
if (statusCode >= 200 && statusCode < 300 && text) {
  const fenced = text.match(/```(?:json)?\s*([\s\S]*?)```/i);
  const candidate = String(fenced?.[1] ?? text).trim();
  try {
    const parsed = JSON.parse(candidate);
    const expected = ['peter', 'stewie', 'peter', 'stewie', 'peter', 'stewie'];
    const turns = Array.isArray(parsed.turns) ? parsed.turns : [];
    const wordCount = turns.reduce((sum, turn) => sum + String(turn.text ?? '').trim().split(/\s+/).filter(Boolean).length, 0);
    dialogueValid = turns.length === 6 && turns.every((turn, index) => String(turn.speaker ?? '').toLowerCase().trim() === expected[index] && String(turn.text ?? '').trim()) && wordCount >= 48;
  } catch {}
}
if (dialogueValid) {
  return [{ json: { use_qwen_fallback: false, response: text, dialogue_provider: 'anthropic', dialogue_model: body?.model ?? 'claude', prompt: promptItem.prompt, research: promptItem.research, seo_brief: promptItem.seo_brief } }];
}
const fallbackReason = statusCode < 200 || statusCode >= 300 ? `${statusCode}_${errorType || 'http_error'}` : text ? 'invalid_dialogue' : 'empty_response';
return [{ json: { use_qwen_fallback: true, prompt: promptItem.prompt, research: promptItem.research, seo_brief: promptItem.seo_brief, dialogue_provider: 'qwen-fallback', fallback_reason: fallbackReason } }];

const topicSlug = $('When Executed by Wrapper').item.json.topicSlug;
const payload = $json;
let raw = '';
if (typeof payload === 'string') raw = payload;
else if (typeof payload.data === 'string') raw = payload.data;
else if (typeof payload.body === 'string') raw = payload.body;
else if (typeof payload.response === 'string') raw = payload.response;
else raw = JSON.stringify(payload);
if (!raw) throw new Error('DIALOGUE_EMPTY_RESPONSE');
let generated = raw;
try { generated = JSON.parse(raw).response ?? raw; } catch {
  const lines = raw.split(/\r?\n/).filter(Boolean);
  const chunks = [];
  let isNdjson = lines.length > 1;
  for (const line of lines) {
    try { chunks.push(JSON.parse(line)); } catch { isNdjson = false; break; }
  }
  if (isNdjson && chunks.every((chunk) => typeof chunk.response === 'string')) generated = chunks.map((chunk) => chunk.response).join('');
}
const fenced = generated.match(/```(?:json)?\s*([\s\S]*?)```/i);
const candidate = String(fenced?.[1] ?? generated).trim();
let dialoguePackage;
const end = candidate.lastIndexOf('}');
for (const start of [0, ...[...candidate.matchAll(/\{/g)].map((match) => match.index)]) {
  if (end < start) continue;
  try {
    const parsed = JSON.parse(candidate.slice(start, end + 1));
    if (Array.isArray(parsed.turns)) { dialoguePackage = parsed; break; }
  } catch {}
}
if (!dialoguePackage || dialoguePackage.turns.length !== 6) throw new Error('DIALOGUE_REQUIRES_SIX_TURNS');
const expected = ['peter', 'stewie', 'peter', 'stewie', 'peter', 'stewie'];
const dialogue = dialoguePackage.turns.map((turn, index) => {
  const speaker = String(turn.speaker ?? '').toLowerCase().trim();
  if (speaker !== expected[index]) throw new Error(`DIALOGUE_SPEAKER_ORDER:${index}`);
  const text = String(turn.text ?? '').replace(/\s+/g, ' ').trim();
  if (!text) throw new Error(`DIALOGUE_EMPTY_TURN:${index}`);
  return { speaker, text, turn_index: index, audio_path: `/media/${topicSlug}-trend-dialogue-${index}-${speaker}.wav` };
});
const wordCount = dialogue.reduce((sum, turn) => sum + turn.text.split(/\s+/).length, 0);
if (wordCount < 48) throw new Error(`DIALOGUE_WORD_COUNT:${wordCount}`);
const metadata = { title: String(dialoguePackage.title ?? ''), focus: String(dialoguePackage.focus ?? ''), visuals: Array.isArray(dialoguePackage.visuals) ? dialoguePackage.visuals : [], research: payload.research };
return dialogue.map((turn) => ({ json: { ...turn, dialogue, ...metadata } }));

const jobs = $items('Normalize Peter and Stewie Dialogue').map((item) => item.json).sort((a, b) => a.turn_index - b.turn_index);
if (jobs.length !== 6) throw new Error(`RENDER_REQUIRES_SIX_DIALOGUE_TURNS:${jobs.length}`);
const first = jobs[0];
const visualCues = first.visuals || [];
